const MESES_I18N = {
  es: ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "set", "oct", "nov", "dic"],
  en: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
  qu: ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "set", "oct", "nov", "dic"],
};
const LOCALE = { es: "es-PE", en: "en-US", qu: "es-PE" };

function getLang() {
  const u = new URLSearchParams(location.search).get("lang");
  if (u && I18N[u]) return u;
  try { const s = localStorage.getItem("muyuy-idioma"); if (s && I18N[s]) return s; } catch {}
  return "es";
}
let LANG = getLang();

function setLang(l) {
  LANG = I18N[l] ? l : "es";
  try { localStorage.setItem("muyuy-idioma", LANG); } catch {}
  document.documentElement.lang = LANG === "qu" ? "qu" : LANG;
}

// tr("clave", {n: 3}) → texto en el idioma actual, con {n} reemplazado
function tr(key, p = {}, dict = I18N) {
  const s = (dict[LANG] && dict[LANG][key]) ?? dict.es[key] ?? key;
  return pegarFlechas(s.replace(/\{(\w+)\}/g, (_, k) => (k in p ? p[k] : `{${k}}`)));
}
// «Ver mis opciones ya →»: la flecha va pegada a la palabra de al lado (espacio que no se parte), así nunca queda
// sola en la última línea del botón cuando el texto no cabe (inglés, quechua, letra grande)
function pegarFlechas(s) {
  if (typeof s !== "string") return s;
  if (/[→←↓↑›‹]/.test(s)) s = s.replace(/ ([→↓↑›])/g, " $1").replace(/([←‹]) /g, "$1 ");
  // «(100 mm)», «S/ 1 438», «20 %»: el número no se separa de su unidad
  // ni un número solo al final («chunkamanta 2»)
  s = s.replace(/ (\d{1,3})$/, " $1");
  return s.replace(/(\d) (mm|cm|km|kg|ha|t|m|%|°C|años|years|wata)(?=[\s).,;:]|$)/g, "$1 $2").replace(/\bS\/ (?=\d)/g, "S/ ");
}
const LT = (key, p) => tr(key, p, I18N_TEC);

