Object.assign(I18N_TEC.es, { refsTit: "Referencias científicas", refsTec: "<ol class=\"refs\"><li>Allen, Pereira, Raes y Smith (1998). Crop evapotranspiration, FAO-56. FAO. <a href=\"https://www.fao.org/4/x0490e/x0490e00.htm\" target=\"_blank\" rel=\"noopener\">www.fao.org/4/x0490e/x0490e00.htm</a></li><li>Steduto, Hsiao, Fereres y Raes (2012). Crop yield response to water, FAO-66. FAO. <a href=\"https://www.fao.org/4/i2800e/i2800e00.htm\" target=\"_blank\" rel=\"noopener\">www.fao.org/4/i2800e/i2800e00.htm</a></li><li>Saxton y Rawls (2006). Soil Science Society of America Journal 70: 1569–1578. <a href=\"https://doi.org/10.2136/sssaj2005.0117\" target=\"_blank\" rel=\"noopener\">doi.org/10.2136/sssaj2005.0117</a></li><li>Renard y Freimund (1994). Journal of Hydrology 157: 287–306. <a href=\"https://doi.org/10.1016/0022-1694(94)90110-4\" target=\"_blank\" rel=\"noopener\">doi.org/10.1016/0022-1694(94)90110-4</a></li><li>Poggio et al. (2021). SoilGrids 2.0. SOIL 7: 217–240. <a href=\"https://doi.org/10.5194/soil-7-217-2021\" target=\"_blank\" rel=\"noopener\">doi.org/10.5194/soil-7-217-2021</a></li><li>Duarte y Sentelhas (2020). NASA/Power para estimar rendimientos. Int. J. Biometeorology 64: 319–329. <a href=\"https://doi.org/10.1007/s00484-019-01810-1\" target=\"_blank\" rel=\"noopener\">doi.org/10.1007/s00484-019-01810-1</a></li><li>Thrasher et al. (2022). NASA NEX-GDDP-CMIP6. Scientific Data 9: 262. <a href=\"https://doi.org/10.1038/s41597-022-01393-4\" target=\"_blank\" rel=\"noopener\">doi.org/10.1038/s41597-022-01393-4</a></li><li>Navarro-Racines et al. (2020). Método delta. Scientific Data 7: 7. <a href=\"https://doi.org/10.1038/s41597-019-0343-8\" target=\"_blank\" rel=\"noopener\">doi.org/10.1038/s41597-019-0343-8</a></li><li>Ramirez-Villegas, Jarvis y Läderach (2013). EcoCrop. Agricultural and Forest Meteorology 170: 67–78. <a href=\"https://doi.org/10.1016/j.agrformet.2011.09.005\" target=\"_blank\" rel=\"noopener\">doi.org/10.1016/j.agrformet.2011.09.005</a></li><li>Egbebiyi et al. (2019). Aptitud y mes de siembra. Climate 7(9): 102. <a href=\"https://doi.org/10.3390/cli7090102\" target=\"_blank\" rel=\"noopener\">doi.org/10.3390/cli7090102</a></li><li>Cai et al. (2020). El Niño en Sudamérica. Nature Reviews Earth & Environment 1: 215–231. <a href=\"https://doi.org/10.1038/s43017-020-0040-3\" target=\"_blank\" rel=\"noopener\">doi.org/10.1038/s43017-020-0040-3</a></li><li>Zhao et al. (2022). Rotaciones con leguminosas. Nature Communications 13: 4926. <a href=\"https://doi.org/10.1038/s41467-022-32464-0\" target=\"_blank\" rel=\"noopener\">doi.org/10.1038/s41467-022-32464-0</a></li><li>Bowles et al. (2020). Diversificación y resiliencia. One Earth 2(3): 284–293. <a href=\"https://doi.org/10.1016/j.oneear.2020.02.007\" target=\"_blank\" rel=\"noopener\">doi.org/10.1016/j.oneear.2020.02.007</a></li><li>Aguilera et al. (2013). Descanso, carbono y nitrógeno en el Altiplano. Mountain Research and Development 33(4): 391–403. <a href=\"https://doi.org/10.1659/MRD-JOURNAL-D-12-00077.1\" target=\"_blank\" rel=\"noopener\">doi.org/10.1659/MRD-JOURNAL-D-12-00077.1</a></li><li>Orlove y Godoy (1986). El muyuy andino. Journal of Ethnobiology 6(1): 169–204. <a href=\"https://ethnobiology.org/sites/default/files/pdfs/JoE/6-1/OrloveGodoy1986.pdf\" target=\"_blank\" rel=\"noopener\">ethnobiology.org/sites/default/files/pdfs/JoE/6-1/OrloveGodoy1986.pdf</a></li></ol><p>Lista completa (31 referencias) en el documento 01, sección 21.</p>" });
Object.assign(I18N_TEC.en, { refsTit: "Scientific references", refsTec: "<ol class=\"refs\"><li>Allen, Pereira, Raes y Smith (1998). Crop evapotranspiration, FAO-56. FAO. <a href=\"https://www.fao.org/4/x0490e/x0490e00.htm\" target=\"_blank\" rel=\"noopener\">www.fao.org/4/x0490e/x0490e00.htm</a></li><li>Steduto, Hsiao, Fereres y Raes (2012). Crop yield response to water, FAO-66. FAO. <a href=\"https://www.fao.org/4/i2800e/i2800e00.htm\" target=\"_blank\" rel=\"noopener\">www.fao.org/4/i2800e/i2800e00.htm</a></li><li>Saxton y Rawls (2006). Soil Science Society of America Journal 70: 1569–1578. <a href=\"https://doi.org/10.2136/sssaj2005.0117\" target=\"_blank\" rel=\"noopener\">doi.org/10.2136/sssaj2005.0117</a></li><li>Renard y Freimund (1994). Journal of Hydrology 157: 287–306. <a href=\"https://doi.org/10.1016/0022-1694(94)90110-4\" target=\"_blank\" rel=\"noopener\">doi.org/10.1016/0022-1694(94)90110-4</a></li><li>Poggio et al. (2021). SoilGrids 2.0. SOIL 7: 217–240. <a href=\"https://doi.org/10.5194/soil-7-217-2021\" target=\"_blank\" rel=\"noopener\">doi.org/10.5194/soil-7-217-2021</a></li><li>Duarte y Sentelhas (2020). NASA/Power para estimar rendimientos. Int. J. Biometeorology 64: 319–329. <a href=\"https://doi.org/10.1007/s00484-019-01810-1\" target=\"_blank\" rel=\"noopener\">doi.org/10.1007/s00484-019-01810-1</a></li><li>Thrasher et al. (2022). NASA NEX-GDDP-CMIP6. Scientific Data 9: 262. <a href=\"https://doi.org/10.1038/s41597-022-01393-4\" target=\"_blank\" rel=\"noopener\">doi.org/10.1038/s41597-022-01393-4</a></li><li>Navarro-Racines et al. (2020). Método delta. Scientific Data 7: 7. <a href=\"https://doi.org/10.1038/s41597-019-0343-8\" target=\"_blank\" rel=\"noopener\">doi.org/10.1038/s41597-019-0343-8</a></li><li>Ramirez-Villegas, Jarvis y Läderach (2013). EcoCrop. Agricultural and Forest Meteorology 170: 67–78. <a href=\"https://doi.org/10.1016/j.agrformet.2011.09.005\" target=\"_blank\" rel=\"noopener\">doi.org/10.1016/j.agrformet.2011.09.005</a></li><li>Egbebiyi et al. (2019). Aptitud y mes de siembra. Climate 7(9): 102. <a href=\"https://doi.org/10.3390/cli7090102\" target=\"_blank\" rel=\"noopener\">doi.org/10.3390/cli7090102</a></li><li>Cai et al. (2020). El Niño en Sudamérica. Nature Reviews Earth & Environment 1: 215–231. <a href=\"https://doi.org/10.1038/s43017-020-0040-3\" target=\"_blank\" rel=\"noopener\">doi.org/10.1038/s43017-020-0040-3</a></li><li>Zhao et al. (2022). Rotaciones con leguminosas. Nature Communications 13: 4926. <a href=\"https://doi.org/10.1038/s41467-022-32464-0\" target=\"_blank\" rel=\"noopener\">doi.org/10.1038/s41467-022-32464-0</a></li><li>Bowles et al. (2020). Diversificación y resiliencia. One Earth 2(3): 284–293. <a href=\"https://doi.org/10.1016/j.oneear.2020.02.007\" target=\"_blank\" rel=\"noopener\">doi.org/10.1016/j.oneear.2020.02.007</a></li><li>Aguilera et al. (2013). Descanso, carbono y nitrógeno en el Altiplano. Mountain Research and Development 33(4): 391–403. <a href=\"https://doi.org/10.1659/MRD-JOURNAL-D-12-00077.1\" target=\"_blank\" rel=\"noopener\">doi.org/10.1659/MRD-JOURNAL-D-12-00077.1</a></li><li>Orlove y Godoy (1986). El muyuy andino. Journal of Ethnobiology 6(1): 169–204. <a href=\"https://ethnobiology.org/sites/default/files/pdfs/JoE/6-1/OrloveGodoy1986.pdf\" target=\"_blank\" rel=\"noopener\">ethnobiology.org/sites/default/files/pdfs/JoE/6-1/OrloveGodoy1986.pdf</a></li></ol><p>Full list (31 references) in document 01, section 21.</p>" });

