// Pinta los textos fijos marcados con data-i18n (texto) o data-i18n-html (con etiquetas)
function applyStatic(root = document, dict = I18N) {
  root.querySelectorAll("[data-i18n]").forEach((el) => (el.textContent = tr(el.dataset.i18n, {}, dict)));
  root.querySelectorAll("[data-i18n-html]").forEach((el) => (el.innerHTML = tr(el.dataset.i18nHtml, {}, dict)));
  if (typeof decorarIconos === "function") decorarIconos(root);
}
// textos del método (antes solo en la vista técnica; ahora también en Información extra → Fuentes)
Object.assign(I18N_TEC.es, {"datT": "Los datos de la NASA que usa Muyuy", "datTabla": "<thead><tr><th>Dato</th><th>Qué mide</th><th>Tamaño del píxel</th><th>Para qué lo usa Muyuy</th></tr></thead><tbody><tr><td>NASA Power</td><td>Lluvia, temperatura, radiación, viento y humedad, cada día desde 1981</td><td>0,5° × 0,625° (~55 km)</td><td>El motor: 45 campañas día a día, corregidas a la altura de su chacra</td></tr><tr><td>GPM Imerg</td><td>Lluvia medida desde el espacio cada media hora</td><td>0,1° (~11 km)</td><td>«Cómo está su chacra ahora»: la lluvia de los últimos días</td></tr><tr><td>SMAP L4</td><td>Humedad del suelo en la superficie y en la zona de raíces</td><td>9 km</td><td>Si hay humedad para sembrar hoy</td></tr><tr><td>Modis NDVI (Terra)</td><td>Verdor de las plantas (índice de vegetación)</td><td>250 m</td><td>Verdor de su chacra frente a otros años</td></tr><tr><td>Modis LST (Terra)</td><td>Temperatura de la superficie de día</td><td>1 km</td><td>Calor sobre la chacra (en lugar de Ecostress)</td></tr><tr><td>HLS (Landsat 8/9 y Sentinel-2)</td><td>Foto de la chacra</td><td>30 m</td><td>Ver su chacra desde el satélite</td></tr><tr><td>Grace y Grace-FO</td><td>Agua total guardada en la región (suelo, acuíferos, nieve)</td><td>~300 km</td><td>Si la reserva de agua de la cuenca baja con los años</td></tr><tr><td>GEDI</td><td>Biomasa y altura de la vegetación con láser</td><td>1 km</td><td>Cuánta vegetación hay alrededor</td></tr><tr><td>SRTM / Nasadem y Copernicus DEM</td><td>Altura del terreno</td><td>30 a 90 m</td><td>Altura, pendiente y erosión</td></tr><tr><td>NEX-GDDP-CMIP6</td><td>Clima proyectado a 2050 (5 modelos)</td><td>0,25°</td><td>Botones «2050» del paso 4</td></tr><tr><td>Ecostress</td><td>Temperatura y estrés hídrico de las plantas</td><td>70 m</td><td>No usado: pide cuenta de Earthdata y no tiene capa abierta (se usa Modis LST)</td></tr></tbody>", "datSvtT": "📡 Satélite o medición en tierra", "datSvt": "<p>El satélite mide desde arriba un cuadro grande (de 30 m a 300 km) y casi siempre de forma indirecta: el color o la temperatura de la superficie. Una estación o un pluviómetro miden en un punto, directo y con precisión, pero solo ahí.</p><p>Juntos son mejores: el satélite llena los lugares donde no hay estación y la estación corrige al satélite. Muyuy corrige NASA Power con la altura de su chacra (−6,5 °C por cada 1000 m) y un factor de lluvia por región; usa el número de heladas que usted recuerda para ajustar las noches frías; y contrasta la lluvia con ERA5. Falta calibrar con las estaciones de Senamhi (Pisco).</p>", "datArmT": "🧩 Cómo se juntan datos de distinto tamaño", "datArm": "<p>Cada dato tiene su tamaño de píxel y su frecuencia: NASA Power ~55 km por día, Imerg 11 km cada media hora, SMAP 9 km, Modis 250 m a 1 km, HLS 30 m, Grace ~300 km por mes, GEDI 1 km.</p><p>Muyuy los lleva a una misma cuadrícula y a un mismo calendario: 398 celdas de NASA Power cubren todo el Perú; el clima de cada celda se baja a la altura exacta de la chacra; los satélites se leen en el punto de la chacra; y todo se resume por mes y por campaña (agosto a julio), que es como piensa el agricultor. Así las rotaciones se comparan con las mismas reglas en todos los lugares.</p>"});
I18N_TEC.es.glos += "<dt>ETc y Kc</dt><dd>ETc = ET₀ × Kc: el agua que pide cada cultivo según su etapa.</dd><dt>Balance de agua</dt><dd>Lluvia menos evapotranspiración, día a día con la raíz de cada cultivo (FAO-56).</dd><dt>Ky</dt><dd>Sensibilidad a la sequía: con Ky menor que 1, el cultivo aguanta mejor.</dd><dt>LST</dt><dd>Temperatura de la superficie que ve el satélite; de día suele superar a la del aire.</dd><dt>Mann-Kendall</dt><dd>Prueba que dice si una tendencia es clara o puede ser azar.</dd>";
Object.assign(I18N_TEC.en, {"datT": "The NASA data Muyuy uses", "datTabla": "<thead><tr><th>Dataset</th><th>What it measures</th><th>Pixel size</th><th>What Muyuy uses it for</th></tr></thead><tbody><tr><td>NASA Power</td><td>Rain, temperature, radiation, wind and humidity, daily since 1981</td><td>0.5° × 0.625° (~55 km)</td><td>The engine: 45 seasons day by day, corrected to your farm's elevation</td></tr><tr><td>GPM Imerg</td><td>Rain measured from space every half hour</td><td>0.1° (~11 km)</td><td>“How your farm is now”: recent rain</td></tr><tr><td>SMAP L4</td><td>Surface and root-zone soil moisture</td><td>9 km</td><td>Whether there is moisture to sow today</td></tr><tr><td>Modis NDVI (Terra)</td><td>Plant greenness (vegetation index)</td><td>250 m</td><td>Your farm's greenness vs. other years</td></tr><tr><td>Modis LST (Terra)</td><td>Daytime land surface temperature</td><td>1 km</td><td>Heat over the farm (instead of Ecostress)</td></tr><tr><td>HLS (Landsat 8/9 and Sentinel-2)</td><td>Photo of the farm</td><td>30 m</td><td>See your field from space</td></tr><tr><td>Grace and Grace-FO</td><td>Total water stored in the region (soil, aquifers, snow)</td><td>~300 km</td><td>Whether the basin's water reserve is falling over the years</td></tr><tr><td>GEDI</td><td>Vegetation biomass and height by lidar</td><td>1 km</td><td>How much vegetation is around</td></tr><tr><td>SRTM / Nasadem and Copernicus DEM</td><td>Terrain elevation</td><td>30 to 90 m</td><td>Elevation, slope and erosion</td></tr><tr><td>NEX-GDDP-CMIP6</td><td>Projected 2050 climate (5 models)</td><td>0.25°</td><td>The “2050” buttons in step 4</td></tr><tr><td>Ecostress</td><td>Plant temperature and water stress</td><td>70 m</td><td>Not used: needs an Earthdata account and has no open layer (Modis LST is used)</td></tr></tbody>", "datSvtT": "📡 Satellite or ground measurement", "datSvt": "<p>A satellite measures a large square from above (30 m to 300 km), almost always indirectly: the colour or temperature of the surface. A weather station or rain gauge measures one point, directly and precisely, but only there.</p><p>Together they are better: satellites fill places without stations and stations correct the satellites. Muyuy corrects NASA Power to your farm's elevation (−6.5 °C per 1000 m) and with a regional rain factor; uses the frosts you remember to adjust cold nights; and cross-checks rain with ERA5. Calibration with Senamhi stations (Pisco) is still pending.</p>", "datArmT": "🧩 How data of different sizes are combined", "datArm": "<p>Each dataset has its own pixel size and frequency: NASA Power ~55 km daily, Imerg 11 km every half hour, SMAP 9 km, Modis 250 m to 1 km, HLS 30 m, Grace ~300 km monthly, GEDI 1 km.</p><p>Muyuy brings them to one grid and one calendar: 398 NASA Power cells cover Peru; each cell's climate is brought down to the farm's exact elevation; satellites are read at the farm's point; and everything is summarised by month and by season (August to July), which is how farmers think. So rotations are compared with the same rules everywhere.</p>"});
I18N_TEC.en.glos += "<dt>ETc and Kc</dt><dd>ETc = ET₀ × Kc: the water each crop demands at each stage.</dd><dt>Water balance</dt><dd>Rain minus evapotranspiration, daily with each crop's roots (FAO-56).</dd><dt>Ky</dt><dd>Drought sensitivity: with Ky below 1, the crop copes better.</dd><dt>LST</dt><dd>Surface temperature seen by the satellite; in daytime it usually exceeds air temperature.</dd><dt>Mann-Kendall</dt><dd>Test of whether a trend is clear or could be chance.</dd>";

// Runasimi: los textos que faltaban (2026-11-14). Es borrador, como el resto del quechua de Muyuy: falta que lo revise
